// modules/library/components/AuthorForm.js
import { useEffect, useState } from "react";
import { authorApi } from "../api/authorApi";
import { useParams, useNavigate } from "react-router-dom";

export default function AuthorForm({ method }) {
  const { id } = useParams();
  const navigate = useNavigate();

  const [form, setForm] = useState({
    name: "",
    country: "",
    biography: ""
  });

  useEffect(() => {
    if (method === "edit") {
      authorApi.get(`/${id}`).then((res) => {
        setForm(res.data);
      });
    }
  }, [id]);

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (method === "create") {
      await authorApi.post("/", form);
    } else {
      await authorApi.put(`/${id}`, form);
    }

    navigate("/library/authors");
  };

  return (
    <div className="content-wrapper p-4">
      <h3>{method === "create" ? "Add New Author" : "Edit Author"}</h3>

      <form onSubmit={handleSubmit} className="mt-3">

        <input
          className="form-control mb-2"
          placeholder="Full Name"
          value={form.name}
          onChange={(e) => setForm({ ...form, name: e.target.value })}
        />

        <input
          className="form-control mb-2"
          placeholder="Country"
          value={form.country}
          onChange={(e) => setForm({ ...form, country: e.target.value })}
        />

        <textarea
          className="form-control mb-2"
          placeholder="Short Biography"
          value={form.biography}
          onChange={(e) => setForm({ ...form, biography: e.target.value })}
        />

        <button className="btn btn-primary">Save</button>
      </form>
    </div>
  );
}
